package com.ycyw.authstub;

import java.time.Duration;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.core.io.Resource;

/**
 * {@code auth.*} settings. {@code privateKeyLocation} (env {@code AUTH_PRIVATE_KEY_LOCATION}) points at
 * a DEV-ONLY PKCS#8 PEM generated by compose's {@code jwt-keys} service; when unset an ephemeral key
 * is generated at startup (tests, IDE runs).
 */
@ConfigurationProperties("auth")
public record AuthStubProperties(Resource privateKeyLocation, String issuer, String audience, Duration maxTtl) {

    public AuthStubProperties {
        issuer = issuer == null ? "ycyw-auth-stub" : issuer;
        audience = audience == null ? "ycyw-chat" : audience;
        maxTtl = maxTtl == null ? Duration.ofHours(8) : maxTtl;
    }
}
